export interface ConnectorConfig {
  /** Trello API key from environment variable TRELLO_API_KEY */
  trelloApiKey: string;
  /** Trello token from environment variable TRELLO_TOKEN */
  trelloToken: string;
  /** The ID of the Trello checklist to add items to */
  checklistId: string;
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch;
}

export interface CalendarEventPayload {
  event: string;
  event_id: string;
  account_id: string;
  meet_link: string;
  attendees?: Array<{ email: string }>;
}

export interface HandleResult {
  checklistItemId: string;
  checklistItemName: string;
  checklistItemState: string;
}

export async function handle(
  payload: CalendarEventPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  // Validate required fields
  if (!payload.attendees || payload.attendees.length === 0) {
    throw new Error('Payload must contain at least one attendee with an email');
  }

  const firstAttendee = payload.attendees[0];
  if (!firstAttendee.email) {
    throw new Error('First attendee must have an email field');
  }

  if (!config.checklistId) {
    throw new Error('Config must include checklistId');
  }

  if (!config.trelloApiKey) {
    throw new Error('Config must include trelloApiKey (TRELLO_API_KEY)');
  }

  if (!config.trelloToken) {
    throw new Error('Config must include trelloToken (TRELLO_TOKEN)');
  }

  const attendeeEmail = firstAttendee.email;

  // Build Trello API URL with query parameters
  const url = new URL(
    `https://api.trello.com/1/checklists/${encodeURIComponent(config.checklistId)}/checkItems`
  );
  url.searchParams.set('key', config.trelloApiKey);
  url.searchParams.set('token', config.trelloToken);
  url.searchParams.set('value', attendeeEmail);

  const response = await fetchImpl(url.toString(), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(
      `Trello API request failed: ${response.status} ${response.statusText} for POST ${url.pathname}`
    );
  }

  const data = (await response.json()) as {
    id: string;
    name: string;
    state: string;
  };

  return {
    checklistItemId: data.id,
    checklistItemName: data.name,
    checklistItemState: data.state,
  };
}

